  const newResponse = new Response(null)
  newResponse.headers.append('set-cookie', newCookies[0])
  c.res = newResponse
  expect(c.res.headers.getSetCookie().length).toBe(cookies.length + newCookies.length)
  expect(c.res.headers.getSetCookie()).toEqual([...cookies, ...newCookies])
})

it('Should keep cookies from both c.res and a newly assigned Response', () => {
  // Middleware has already set a cookie on the context response.
  c.res.headers.append('set-cookie', 'middleware=hello; Path=/')

  // The handler returns a new Response with its own Set-Cookie header.
  const handlerResponse = new Response('ok', {
    headers: {
      'set-cookie': 'handler=world; Path=/; HttpOnly',
    },
  })
  c.res = handlerResponse

  expect(c.res.headers.getSetCookie()).toEqual([
    'middleware=hello; Path=/',
    'handler=world; Path=/; HttpOnly',
  ])
})

it('Should not duplicate cookies when the new Response is derived from c.res', () => {
  c.res.headers.append('set-cookie', 'session=abc; Path=/')

  // `c.text()` copies the current response headers into the new Response.
  c.res = c.text('ok')

  expect(c.res.headers.getSetCookie()).toEqual(['session=abc; Path=/'])
})

